import collections,hashlib,json,os,re,statistics,subprocess,tempfile,time
from pathlib import Path
os.sched_setaffinity(0,{0})
binaries={'parent':'build/review-j01-preload/release/mus-bot','candidate':'build/review-j01-adapter/release/mus-bot'}
data={'method':'Three alternating paired runs on CPU0. 64000 sequential JSON queries per run; include all lances, mus, discard and off-abstraction responses. RSS is the process VmHWM sampled during queries. Public backends are new optional paths, measured absolutely. No concurrent own tests or builds.','parent_commit':'f62ad27','runs':[],'summary':[]}
data['binary_sha256']={k:hashlib.sha256(Path(v).read_bytes()).hexdigest() for k,v in binaries.items()}
data['solver_sha256']={k:hashlib.sha256(Path(v.replace('mus-bot','mus-solver')).read_bytes()).hexdigest() for k,v in binaries.items()}
assert len(set(data['solver_sha256'].values()))==1
output=Path('/tmp/mus-review-j01-adapter-performance.json')
def save():output.write_text(json.dumps(data,indent=2)+'\n')
def query(phase='grande',public=False):
 prior={'grande':0,'chica':1,'pares':2,'juego':3,'punto':3,'mus':0,'discard':0}[phase]
 q={'player':0,'phase':phase,'hand':[0]*7+[4],'previous_strengths':([3,1,3] if public else [0,0,0])[:prior],
    'match_scores':[10+(public and prior>=2),12+2*(public and prior==3)],'hand_start_scores':[10,12],
    'pending_wager_total':2 if public and prior else 0,'legal_actions':[{'type':'pass'},{'type':'ordago'}]+[{'type':'raise','amount':i} for i in [2,4,7,10]]}
 if phase=='punto':q['hand']=[4]+[0]*7
 if phase=='mus':q['legal_actions']=[{'type':'mus'},{'type':'no_mus'}]
 if phase=='discard':q['legal_actions']=[{'type':'discard','mask':i} for i in [1,3,7,15]]
 return q
def corpus(public=False,hybrid=False):
 qs=[query(p,public) for p in ['grande','chica','pares','juego','punto','mus','discard']]
 for amount in [2,3,4,6,9,40]:
  q=query('grande',public);q['history']=[{'player':0,'type':'pass'},{'player':1,'type':'raise','amount':amount}]
  q['legal_actions']=[{'type':'reject'},{'type':'accept'},{'type':'ordago'},{'type':'raise','amount':4}];qs.append(q)
 q=query('grande',public);q['history']=[{'player':0,'type':'pass'},{'player':1,'type':'raise','amount':2},{'player':0,'type':'raise','amount':2},{'player':1,'type':'raise','amount':2}]
 q['legal_actions']=[{'type':'reject'},{'type':'accept'},{'type':'ordago'},{'type':'raise','amount':4}];qs.append(q)
 if hybrid:
  for i,q in enumerate(qs):
   q['match_scores']=q['hand_start_scores']=[30,30] if i%2==0 else [30,39]
 data.setdefault('corpora',{})[('public' if public else 'legacy')+('-hybrid' if hybrid else '')]=qs
 return [json.dumps(q,separators=(',',':'))+'\n' for q in qs]
def run(group,version,extra,queries,repeat):
 command=[binaries[version],*extra,'--seed','123','--no-score-adjustment']
 start=time.perf_counter();p=subprocess.Popen(command,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
 digest=hashlib.sha256();latencies=[];rss=0;methods=collections.Counter()
 for i in range(64000):
  begin=time.perf_counter();p.stdin.write(queries[i%len(queries)]);p.stdin.flush();line=p.stdout.readline();elapsed=time.perf_counter()-begin
  if not line:raise RuntimeError((command,p.poll(),p.stderr.read()))
  result=json.loads(line);assert result['ok'],result
  methods[result['diagnostic']['method']]+=1;latencies.append(elapsed);digest.update(line.encode())
  if i%50==0:
   status=Path(f'/proc/{p.pid}/status').read_text();rss=max(rss,int(re.search(r'VmHWM:\s+(\d+)',status)[1]))
 p.stdin.close();err=p.stderr.read();assert p.wait()==0 and not err,err
 row={'group':group,'version':version,'repeat':repeat,'command':command,'wall_seconds':time.perf_counter()-start,'peak_rss_kib':rss,'mean_query_ms':1000*statistics.mean(latencies[1:]),'p95_query_ms':1000*sorted(latencies[1:])[int(.95*(len(latencies)-1))],'output_sha256':digest.hexdigest(),'methods':dict(methods)}
 data['runs'].append(row);save();print(json.dumps(row),flush=True)
def summary(group,paired=True):
 rows=[r for r in data['runs'] if r['group']==group];assert len({r['output_sha256'] for r in rows})==1
 result={'group':group,'outputs_identical':True}
 for metric in ['wall_seconds','peak_rss_kib','mean_query_ms','p95_query_ms']:
  b=statistics.median(r[metric] for r in rows if r['version']=='candidate');result[metric]={'candidate':b}
  if paired:
   a=statistics.median(r[metric] for r in rows if r['version']=='parent');result[metric].update(parent=a,change_percent=100*(b/a-1))
 data['summary'].append(result);save();print('SUMMARY',json.dumps(result),flush=True)
 if paired and (result['wall_seconds']['change_percent']>=20 or result['peak_rss_kib']['change_percent']>=25):raise RuntimeError('Five confirmation pairs required')
with tempfile.TemporaryDirectory(prefix='mus-review-j01-adapter-') as tmp:
 root=Path(tmp);legacy=root/'legacy.cfr';public=root/'public.cfr';scores=root/'scores';scores.mkdir()
 subprocess.run(['build/debug/mus_adapter_tests',str(legacy),str(scores)],check=True,stdout=subprocess.DEVNULL)
 subprocess.run(['build/debug/mus_adapter_tests','--public-fixture',str(public)],check=True,stdout=subprocess.DEVNULL)
 for group,extra,qs in [('legacy-raw',['--load',str(legacy)],corpus()),('legacy-text',['--strategy',str(legacy)+'.txt'],corpus()),('hybrid-text',['--strategy',str(legacy)+'.txt','--score-table',str(scores/'values.txt'),'--score-strategies',str(scores)],corpus(hybrid=True))]:
  for repeat in range(3):
   for version in (['parent','candidate'] if repeat%2==0 else ['candidate','parent']):run(group,version,extra,qs,repeat+1)
  summary(group)
 for flag,suffix in [('--load',''),('--strategy','.txt')]:
  group='public-'+('raw' if not suffix else 'text')
  for repeat in range(3):run(group,'candidate',[flag,str(public)+suffix],corpus(public=True),repeat+1)
  summary(group,False)
print('ALL_CHECKS_PASSED',flush=True)
